"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq

Cell = tuple[int, int]  # (row, col)

WALL = "#"
FLOOR = "."
DOOR = "D"
START = "S"
GOAL = "G"

ENTER_COST = {FLOOR: 1, DOOR: 3, START: 1, GOAL: 1}

# Right, down, left, up: a fixed order keeps ties deterministic.
NEIGHBOURS = ((0, 1), (1, 0), (0, -1), (-1, 0))


def _locate(grid: list[str]) -> tuple[Cell, Cell] | None:
    """Return (start, goal) cells, or None if either marker is missing."""
    start = goal = None
    for row, line in enumerate(grid):
        for col, char in enumerate(line):
            if char == START and start is None:
                start = (row, col)
            elif char == GOAL and goal is None:
                goal = (row, col)
    if start is None or goal is None:
        return None
    return start, goal


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    ends = _locate(grid)
    if ends is None:
        return None
    start, goal = ends

    height = len(grid)
    # Ragged rows are tolerated: bounds are checked against each row's length.
    def inside(row: int, col: int) -> bool:
        return 0 <= row < height and 0 <= col < len(grid[row])

    def enter_cost(row: int, col: int) -> int | None:
        char = grid[row][col]
        if char not in ENTER_COST:
            return None  # wall or unknown tile
        return ENTER_COST[char]

    best: dict[Cell, int] = {start: 0}
    came_from: dict[Cell, Cell] = {}
    queue: list[tuple[int, Cell]] = [(0, start)]

    while queue:
        cost, cell = heapq.heappop(queue)
        if cost > best.get(cell, cost):
            continue  # stale entry left behind by a cheaper relaxation
        if cell == goal:
            break
        row, col = cell
        for d_row, d_col in NEIGHBOURS:
            next_row, next_col = row + d_row, col + d_col
            if not inside(next_row, next_col):
                continue
            step = enter_cost(next_row, next_col)
            if step is None:
                continue
            next_cost = cost + step
            next_cell = (next_row, next_col)
            if next_cell not in best or next_cost < best[next_cell]:
                best[next_cell] = next_cost
                came_from[next_cell] = cell
                heapq.heappush(queue, (next_cost, next_cell))

    if goal not in best:
        return None

    path: list[Cell] = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])
    path.reverse()
    return path

